using System.ComponentModel.DataAnnotations;
namespace Fleet.Api.Models;
public sealed class User { public int Id{get;set;} [MaxLength(80)] public required string Username{get;set;} [MaxLength(500)] public required string PasswordHash{get;set;} [MaxLength(20)] public required string Role{get;set;} public int? DriverId{get;set;} public DateTime CreatedAt{get;set;}=DateTime.UtcNow; }
public sealed class Vehicle { public int Id{get;set;} [MaxLength(20)] public required string PlateNumber{get;set;} [MaxLength(100)] public required string MakeModel{get;set;} public int Year{get;set;} public int Odometer{get;set;} [MaxLength(20)] public string Status{get;set;}="Available"; public DateTime CreatedAt{get;set;}=DateTime.UtcNow; }
public sealed class Driver { public int Id{get;set;} [MaxLength(120)] public required string FullName{get;set;} [MaxLength(50)] public required string LicenseNumber{get;set;} public DateOnly LicenseExpiresOn{get;set;} public bool Active{get;set;}=true; }
public sealed class Assignment { public int Id{get;set;} public int VehicleId{get;set;} public Vehicle? Vehicle{get;set;} public int DriverId{get;set;} public Driver? Driver{get;set;} public DateTime StartsAt{get;set;} public DateTime? EndsAt{get;set;} [MaxLength(200)] public required string Purpose{get;set;} public int CreatedById{get;set;} public User? CreatedBy{get;set;} public DateTime CreatedAt{get;set;}=DateTime.UtcNow; }
public sealed class MaintenanceRecord { public int Id{get;set;} public int VehicleId{get;set;} public Vehicle? Vehicle{get;set;} [MaxLength(100)] public required string ServiceType{get;set;} public int Odometer{get;set;} public decimal Cost{get;set;} public DateOnly ServicedOn{get;set;} [MaxLength(500)] public string Notes{get;set;}=""; }
